function Get-MetaLocalConsumerMatches([string]$Mcp,[string]$Inspector){
 $root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../../..'));$tracked=@(& git -C $root -c core.quotepath=false ls-files 2>$null);if($LASTEXITCODE -ne 0){throw 'LOCAL_INVENTORY'};$localConsumerMatches=[Collections.Generic.List[object]]::new();$examined=0;$missing=0
