 return @{trackedTextFilesExamined=$examined;missingTrackedFilesSkipped=$missing;matches=@($localConsumerMatches.ToArray());coverage='EXISTING_TRACKED_REPOSITORY_TEXT_AND_TWO_EXACT_DPAPI_ARTIFACTS_NOT_EXTERNAL_CONSUMERS';fileWrites=0}
}
function Get-MetaConsumerFailureMetadata($Record){
