 $leaf=if($Record.InvocationInfo.ScriptName){[IO.Path]::GetFileName($Record.InvocationInfo.ScriptName)}else{$null};if($leaf -cnotin @('consumer-meta-readonly-v2-20261021.ps1','phase10-independent-incident-inventory.ps1','incident-common.ps1','scheduler-live-helpers.ps1')){$leaf=$null}
 $line=if($leaf -and $Record.InvocationInfo.ScriptLineNumber -ge 1 -and $Record.InvocationInfo.ScriptLineNumber -le 5000){$Record.InvocationInfo.ScriptLineNumber}else{$null}
 return @{errorId=$fqid;scriptLeaf=$leaf;scriptLine=$line}
}
